// Merge stats + vendor data, score each vendor
const stats = $('Fetch All Stats').item.json;
const vendorData = $('Fetch Vendor List').item.json;

const now = new Date();
const lastMonth = new Date(now.getFullYear(), now.getMonth()-1, 1);
const monthLabel = lastMonth.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });

// Use vendors from vendor API or fall back to inferring from recent entries
const vendors = vendorData.vendors || [];

// If vendor API not yet built, synthesize mock scorecards from material data
const materialBreakdown = stats.by_material || [];
const summary = stats.summary || {};

// Build vendor scorecards
// Score formula: volume score (40) + quality score (30) + timeliness score (30)
const scorecards = vendors.length > 0 ? vendors.map(v => {
  const volumeScore = Math.min(40, Math.round((v.total_kg / (summary.total_purchased || 1)) * 40 * 3));
  const qualityScore = Math.max(0, 30 - Math.round(v.loss_rate * 1.5));
  const timelinessScore = v.avg_delivery_days <= 1 ? 30 : v.avg_delivery_days <= 3 ? 22 : v.avg_delivery_days <= 7 ? 14 : 5;
  const totalScore = volumeScore + qualityScore + timelinessScore;
  const grade = totalScore >= 85 ? 'A' : totalScore >= 70 ? 'B' : totalScore >= 50 ? 'C' : 'D';
  const gradeColor = grade === 'A' ? '#4ADE80' : grade === 'B' ? '#F59E0B' : grade === 'C' ? '#FB923C' : '#F87171';
  return { ...v, volumeScore, qualityScore, timelinessScore, totalScore, grade, gradeColor };
}).sort((a, b) => b.totalScore - a.totalScore)
: [
  // Mock data if vendor endpoint not built yet
  { name: 'Vendor A', total_kg: 1200, loss_rate: 4.2, avg_delivery_days: 1, volumeScore: 35, qualityScore: 28, timelinessScore: 30, totalScore: 93, grade: 'A', gradeColor: '#4ADE80', material: 'PET' },
  { name: 'Vendor B', total_kg: 850, loss_rate: 8.1, avg_delivery_days: 2, volumeScore: 25, qualityScore: 24, timelinessScore: 22, totalScore: 71, grade: 'B', gradeColor: '#F59E0B', material: 'HDPE' },
  { name: 'Vendor C', total_kg: 430, loss_rate: 15.3, avg_delivery_days: 4, volumeScore: 13, qualityScore: 18, timelinessScore: 14, totalScore: 45, grade: 'D', gradeColor: '#F87171', material: 'Mixed' },
  { name: 'Vendor D', total_kg: 690, loss_rate: 6.8, avg_delivery_days: 3, volumeScore: 20, qualityScore: 26, timelinessScore: 22, totalScore: 68, grade: 'C', gradeColor: '#FB923C', material: 'PP' }
];

const topVendor = scorecards[0];
const bottomVendor = scorecards[scorecards.length - 1];

return [{ json: { scorecards, monthLabel, topVendor, bottomVendor, summary } }];

// After all vendors processed, send summary to ops team
const allItems = $input.all();
const monthLabel = $('Score All Vendors').item.json.monthLabel;

const grades = allItems.map(item => item.json);
const topVendor = grades.sort((a,b) => b.totalScore - a.totalScore)[0];
const bottomVendor = grades[grades.length-1];

const gradeDistribution = grades.reduce((acc, v) => {
  acc[v.grade] = (acc[v.grade]||0)+1;
  return acc;
},{});

const whatsappMsg = `📊 *TraceFlow Monthly Vendor Scorecards*\n\n*Month:* ${monthLabel}\n*Vendors Scored:* ${grades.length}\n\n🥇 *Top Performer:* ${topVendor?.vendorName} — Grade ${topVendor?.grade} (${topVendor?.totalScore}/100)\n⚠️ *Needs Attention:* ${bottomVendor?.vendorName} — Grade ${bottomVendor?.grade} (${bottomVendor?.totalScore}/100)\n\nGrade Breakdown:\nA: ${gradeDistribution['A']||0} · B: ${gradeDistribution['B']||0} · C: ${gradeDistribution['C']||0} · D: ${gradeDistribution['D']||0}\n\nScorecards sent to all vendors.`;

return [{ json: { whatsappMsg, topVendor, bottomVendor, totalVendors: grades.length } }];
